// 拉普拉斯平滑参数 alpha 即为 x
// 训练集：垃圾邮件(S)10 封，总词数 20；正常邮件(H)20 封，总词数 30
// 词汇表大小 V=2 ("free", "money")
// 新邮件含 "free" 和 "money"
// 计算 P(S|W) 赋给 y
let result = [];
for (let i = 0; i < 100; i++) {
  let alpha = 0.1 + i * (5 - 0.1) / 99;
  let p_s = 1/3;
  let p_h = 2/3;
  let p_free_s = (8 + alpha) / (20 + 2 * alpha);
  let p_money_s = (5 + alpha) / (20 + 2 * alpha);
  let p_free_h = (1 + alpha) / (30 + 2 * alpha);
  let p_money_h = (1 + alpha) / (30 + 2 * alpha);
  let p_w_s = p_free_s * p_money_s;
  let p_w_h = p_free_h * p_money_h;
  let y = (p_s * p_w_s) / (p_s * p_w_s + p_h * p_w_h);
  result.push({x: alpha, y: y});
}
